-- 001_identity: users, accounts, memberships, wallet identities, sessions, challenges,
-- idempotency keys and the append-only audit log. Plain PostgreSQL (also runs on PGlite).
-- All ids are opaque text generated by the application. Timestamps are written by the app clock.
-- Rollback (pre-release only; destroys all accounts): drop table audit_events, idempotency_keys, wallet_challenges, sessions, linked_identities, memberships, accounts, users
-- (in that order, cascade) and the function audit_events_immutable(). Every later migration depends on these tables; roll those back first.

create table users (
  id          text primary key,
  created_at  timestamptz not null
);

create table accounts (
  id          text primary key,
  name        text,
  created_at  timestamptz not null
);

create table memberships (
  id          text primary key,
  account_id  text not null references accounts (id),
  user_id     text not null references users (id),
  role        text not null check (role in ('owner', 'admin', 'billing', 'member')),
  created_at  timestamptz not null,
  unique (account_id, user_id)
);
create index memberships_user_idx on memberships (user_id, created_at);

-- Identity = protocol + canonical address + chain policy. chain_policy is 'eip155' for EVM (an EOA is
-- the same key on every EVM chain; the concrete chain id is bound into each challenge) and 'tron:<network>'.
-- Rows are soft-unlinked so audit history stays referable; only active rows are unique.
create table linked_identities (
  id            text primary key,
  user_id       text not null references users (id),
  protocol      text not null check (protocol in ('evm', 'tron')),
  address       text not null,
  chain_policy  text not null,
  created_at    timestamptz not null,
  unlinked_at   timestamptz
);
create unique index linked_identities_active_uq
  on linked_identities (protocol, address, chain_policy) where unlinked_at is null;
create index linked_identities_user_idx on linked_identities (user_id) where unlinked_at is null;

-- Server-side sessions. Only an HMAC digest of the cookie token is stored.
create table sessions (
  id                text primary key,
  token_hash        text not null unique,
  user_id           text not null references users (id),
  account_id        text not null references accounts (id),
  authenticated_at  timestamptz not null,   -- last proof of possession; drives step-up checks
  created_at        timestamptz not null,
  expires_at        timestamptz not null,
  revoked_at        timestamptz
);
create index sessions_user_idx on sessions (user_id);

-- Single-use wallet challenges. consumed_at is set by one conditional UPDATE, so exactly one caller wins.
create table wallet_challenges (
  id            text primary key,
  purpose       text not null check (purpose in ('login', 'link')),
  protocol      text not null check (protocol in ('evm', 'tron')),
  address       text not null,
  chain_id      text not null,
  chain_policy  text not null,
  nonce         text not null unique,
  message       text not null,
  user_id       text references users (id),     -- link purpose: the user that must be signed in
  session_id    text references sessions (id),  -- link purpose: the session that requested it
  created_at    timestamptz not null,
  expires_at    timestamptz not null,
  consumed_at   timestamptz,
  check ((purpose = 'link') = (user_id is not null and session_id is not null))
);

-- Persisted key is (account, operation, key), matching contracts decideIdempotency semantics.
create table idempotency_keys (
  account_id          text not null references accounts (id),
  operation           text not null,
  key                 text not null,
  payload_hash        text not null,
  state               text not null check (state in ('in_flight', 'completed')),
  created_at          timestamptz not null,
  completed_at        timestamptz,
  status_code         integer,
  result              jsonb,                    -- secret-free response metadata
  replay_ciphertext   text,                     -- AES-256-GCM sealed secret, only inside the replay window
  replay_session_id   text,
  replay_expires_at   timestamptz,
  primary key (account_id, operation, key),
  check (state = 'in_flight' or (result is not null and completed_at is not null))
);

create table audit_events (
  id             text primary key,
  account_id     text references accounts (id),
  actor_user_id  text references users (id),
  action         text not null,
  target_type    text,
  target_id      text,
  request_id     text,
  metadata       jsonb not null default '{}'::jsonb,   -- never holds secrets
  created_at     timestamptz not null
);
create index audit_events_account_idx on audit_events (account_id, created_at);

create function audit_events_immutable() returns trigger language plpgsql as $$
begin
  raise exception 'audit_events is append-only';
end $$;
create trigger audit_events_no_update before update or delete on audit_events
  for each row execute function audit_events_immutable();
